        beq     cr7, dr_templates_L13
        cmpwi   cr7, data, 0
        rlwimi  addr, rtn_addr, 0, 16, 31               // addr[15:0] = rtn_addr[15:0]
        lwz     data, 0x6348(base_disp)
        stwu    addr, 4(immed_data)
        srwi    addr, rtn_addr, 16
        bge     cr7, dr_templates_L18
        addi    addr, addr, 1
dr_templates_L18:
        rlwimi  data, addr, 0, 16, 31                   // data[15:0] = addr[15:0]
        stwu    data, 4(immed_data)
        lwz     data, 0x6350(base_disp)
        b       dr_templates_L15

// Leave translated code (or abandon a lookup) and continue in the
// interpreter with the instruction at pc - 2.
dr_exit_to_interpreter:
        lha     prefetch_data, -2(pc)                   // prefetch_data = that instruction's opcode
        rlwimi  disp_table, prefetch_data, 3, 13, 28    // DECODE1: disp_table[18:3] = opcode in prefetch_data
        mtlr    disp_table                              // DECODE2: LR = address of the next dispatch entry
        lwz     r23, dr_dispatch_vector(EmulatorStatePtr)  // restore dr_entry
        lha     prefetch_data, 0(pc)                    // prefetch the word after it
        bflr_likely cr_special_event_pending            // DISPATCH unless a special event is pending
        lwz     rtn_addr, special_event_hook(EmulatorStatePtr)
        rlwimi  sr_and_flags, pc, 9, 22, 22             // sr_and_flags[9] = pc[0]
        mtlr    rtn_addr
        mtcrf   0x0F, sr_and_flags                      // cr4..cr7 = sr_and_flags[15:0]
        crmove  cr_special_event_pending, 4*cr5+gt
        mtctr   disp_table                              // DECODE2: CTR = address of the next dispatch entry
        blrl

// A translated block ends with a call to this routine when the block that
// follows is at a fixed address: pc already holds that address (plus 2).
// Look it up; if a translation exists, dr_chain_block replaces the call
// that came here with a direct branch to it, otherwise translate it.
// (Also reached by falling out of the special event processing in
// dr_exit_to_interpreter.)
dr_block_exit:
        lwz     r23, dr_hash_table(EmulatorStatePtr)
        rlwimi  r23, pc, 4, 16, 26                      // r23[15:5] = pc[11:1]
        lwz     data, 0(r23)
        cmpw    cr7, data, pc
        lwzu    data, 8(r23)
        bt_likely 4*cr7+eq, dr_chain_block
        cmpw    cr7, data, pc
        lwzu    data, 8(r23)
        bt_likely 4*cr7+eq, dr_chain_block
        cmpw    cr7, data, pc
        lwzu    data, 8(r23)
        bt_likely 4*cr7+eq, dr_chain_block
        cmpw    cr7, data, pc
        addi    r23, r23, 8
        beq     cr7, dr_chain_block
        b       dr_translate_miss

// The target of a block-ending branch has been found in the lookup table.
// Overwrite the call that brought control here with a direct branch to
// the target block, so that next time the two blocks run back to back
// without entering the run-time at all.
dr_chain_block:
        lwz     immed_data, dr_code_base(EmulatorStatePtr)
        lwz     data, -4(r23)
        mflr    addr
        mtctr   data
        lwz     immed_data, 0x7694(immed_data)          // template: unconditional branch
        subf    rtn_addr, addr, data                    // rtn_addr = data - addr
        addi    rtn_addr, rtn_addr, 4
        rlwimi  immed_data, rtn_addr, 0, 6, 29          // immed_data[25:2] = rtn_addr[25:2]
        stw     immed_data, -4(addr)                    // patch the call site
        addi    addr, addr, -4
        dcbf    0, addr                                 // make the patched word visible to instruction fetch
        sync
        icbi    0, addr
        sync
        isync
        bctr

// Entered from translated code at a branch whose target is only known at
// run time (RTS, JMP (An), ...).  The two words following the call are a
// one-entry cache: the 68K target seen last time and its translation.
dr_indirect_exit:
        crset   cr_dr_busy
        lha     rtn_addr, 0(pc)
        addi    pc, pc, 2
        crclr   cr_dr_busy
        mflr    base_disp
        cmpwi   cr7, rtn_addr, -0x5502
        cmpwi   cr6, rtn_addr, -0x1FE
        lwz     addr, 0(base_disp)                      // cached 68K address
        bt_unlikely cr_special_event_pending, dr_exit_to_interpreter
        lwz     data, 4(base_disp)                      // cached translation
        bt_unlikely 4*cr7+eq, dr_exit_to_interpreter
        cmpw    cr5, addr, pc
        bt_unlikely 4*cr6+eq, dr_exit_to_interpreter
        mtctr   data
        mtcrf   0x01, pc                                // cr7 = pc[3:0]
        beqctr  cr5                                     // same target as last time: go straight there
        bf_likely 4*cr7+so, dr_stale_block_L1
        b       dr_exit_to_interpreter
        b       dr_promote_hit
        ALIGN(64)

// Lookup hit in a slot other than the first: swap the entry to the front
// of its set before jumping to it.
dr_promote_hit:
        lwz     rtn_addr, -16(base_disp)
        stw     pc, -16(base_disp)
        lwz     data, -4(base_disp)
        lwz     immed_data, -12(base_disp)
        stw     rtn_addr, -8(base_disp)
        mtctr   data
        stw     data, -12(base_disp)
        stw     immed_data, -4(base_disp)
        bctr

// ===========================================================================
// Dynamic recompiler: run-time dispatch
// ===========================================================================
// The interpreter comes here (through dr_entry, when cr_dr_active is set)
// after every instruction that changes the flow of control, with LR
// holding the dispatch table entry it would otherwise have used.
// If a translation of the code at pc - 2 exists, run it; otherwise
// translate it first.  Returning through LR instead simply interprets the
// instruction.
// The lookup table maps 68K addresses to translated code.  Bits 11:1 of
// pc select one of 2048 sets; a set is 32 bytes, four {68K address, code
// address} pairs, searched in order.  The table is 64 KB and 64 KB
// aligned, so the set address is formed by inserting pc bits into the
// table's base address.
dr_dispatch:
        lha     rtn_addr, -2(pc)                        // opcode of the instruction about to run
        lwz     addr, dr_flush_pending(EmulatorStatePtr)
        lwz     data, dr_invalidate_pending(EmulatorStatePtr)
        cmpwi   cr6, rtn_addr, -0x5502                  // 0xAAFE: never translated
        cmpwi   cr7, rtn_addr, -0x1FE                   // 0xFE02: never translated
        bt_unlikely cr_special_event_pending, dr_exit_to_interpreter
        beqlr   cr6
        beqlr   cr7
        cmplwi  cr6, addr, 0x0000                       // a whole-cache flush is in progress
        cmplwi  cr7, data, 0x0000                       // address ranges are waiting to be invalidated
        bne     cr6, dr_flush_step
        bne     cr7, dr_invalidate_step

dr_lookup:
        lwz     base_disp, dr_hash_table(EmulatorStatePtr)  // lookup table base (64 KB aligned)
        rlwimi  base_disp, pc, 4, 16, 26                // select the set: pc[11:1]
        lwz     data, 0(base_disp)
        mtcrf   0x01, pc                                // cr7 = pc[3:0]
        lwz     rtn_addr, 4(base_disp)
        bso     cr7, dr_exit_to_interpreter             // odd address: let the interpreter raise the error
        cmpw    cr7, data, pc
        mtctr   rtn_addr
        lwzu    data, 8(base_disp)
        beqctr  cr7                                     // hit in the first slot
        cmpw    cr7, data, pc
        lwzu    data, 8(base_disp)
        beq     cr7, dr_promote_hit
        cmpw    cr7, data, pc
        lwzu    data, 8(base_disp)
        beq     cr7, dr_promote_hit
        cmpw    cr7, data, pc
        addi    base_disp, base_disp, 8
        bt_unlikely 4*cr7+eq, dr_promote_hit
        mr      r23, base_disp                          // miss: remember where the search ended
        sth     zero, 0xB34(EmulatorStatePtr)
        b       dr_translate_miss_L1

// Discard every translation.  The lookup table and then the page bitmap
// are cleared 2 KB at a time with dcbz, checking for special events
// between chunks; progress is kept in the state block so the work resumes
// on the next dispatch.
dr_flush_step:
        lwz     addr, 0xB70(EmulatorStatePtr)
        lwz     data, dr_hash_table(EmulatorStatePtr)
        cmplwi  cr6, addr, 0x0000
        li      rtn_addr, 32
        subf    rtn_addr, addr, rtn_addr                // rtn_addr = rtn_addr - addr
        mulli   rtn_addr, rtn_addr, 0x800
        add     data, data, rtn_addr
dr_flush_step_L1:
        beq     cr6, dr_flush_step_L3
        bt      cr_special_event_pending, dr_flush_done_L2
        li      rtn_addr, 64
        mtctr   rtn_addr
        addi    addr, addr, -1
        cmplwi  cr6, addr, 0x0000
dr_flush_step_L2:
        dcbz    0, data
        addi    data, data, 32
        bdnz    dr_flush_step_L2                        // CTR -= 1; branch while CTR != 0
        b       dr_flush_step_L1
dr_flush_step_L3:
        lwz     addr, 0xB74(EmulatorStatePtr)
        lwz     data, dr_page_bitmap(EmulatorStatePtr)
        lwz     rtn_addr, 0xB94(EmulatorStatePtr)
        cmplwi  cr6, data, 0x0000
        cmplwi  cr7, addr, 0x0040
        subf    rtn_addr, addr, rtn_addr                // rtn_addr = rtn_addr - addr
        slwi    rtn_addr, rtn_addr, 5
        add     data, data, rtn_addr
        li      immed_data, 64
dr_flush_step_L4:
        beq     cr6, dr_flush_done
        bt      cr_special_event_pending, dr_flush_done_L1
        bge     cr7, dr_flush_step_L5
        mr      immed_data, addr
dr_flush_step_L5:
        mtctr   immed_data
        subf    addr, immed_data, addr                  // addr = addr - immed_data
        cmplwi  cr6, addr, 0x0000
        cmplwi  cr7, addr, 0x0040
dr_flush_step_L6:
        dcbz    0, data
        addi    data, data, 32
        bdnz    dr_flush_step_L6                        // CTR -= 1; branch while CTR != 0
        b       dr_flush_step_L4

dr_flush_done:
        stw     zero, dr_invalidate_pending(EmulatorStatePtr)
        stw     zero, 0xB7C(EmulatorStatePtr)
        stw     zero, 0xB70(EmulatorStatePtr)
        stw     zero, 0xB74(EmulatorStatePtr)
        lwz     addr, dr_cache_start(EmulatorStatePtr)
        stw     addr, dr_cache_ptr(EmulatorStatePtr)
        stw     zero, dr_flush_pending(EmulatorStatePtr)
        b       dr_lookup
dr_flush_done_L1:
        stw     addr, 0xB74(EmulatorStatePtr)
        b       dr_flush_done_L3
dr_flush_done_L2:
        stw     addr, 0xB70(EmulatorStatePtr)
dr_flush_done_L3:
        mfcr    rtn_addr
        rlwinm  rtn_addr, rtn_addr, 0, 6, 4             // rtn_addr = rtn_addr & 0xFBFFFFFF
        mtcrf   0x40, rtn_addr                          // cr1 = rtn_addr[27:24]
        b       dr_exit_to_interpreter

// Service one pending range-invalidation request: scan part of the lookup
// table and drop every translation whose 68K address lies in the range.
// Requests are flagged in a bit mask that is updated with lwarx/stwcx.
// because it is also written from outside the emulator's normal flow.
dr_invalidate_step:
        lwz     addr, dr_invalidate_requests(EmulatorStatePtr)
        cmplwi  cr6, data, 0x0000
        cntlzw  base_disp, data                         // base_disp = number of leading zero bits in data
        beq     cr6, dr_lookup
        stw     base_disp, 0xB84(EmulatorStatePtr)
        slwi    base_disp, base_disp, 4
        add     base_disp, addr, base_disp
        lwz     immed_data, 12(base_disp)
        stw     base_disp, 0xB88(EmulatorStatePtr)
        lwz     addr, 0(base_disp)
        cmplwi  cr6, immed_data, 0x0040
        lwz     data, 4(base_disp)
        lwz     base_disp, 8(base_disp)
        blt     cr6, dr_invalidate_step_L1
        li      immed_data, 64
dr_invalidate_step_L1:
        bt      cr_special_event_pending, dr_flush_done_L3
        mtctr   immed_data
        stw     immed_data, 0xB8C(EmulatorStatePtr)
dr_invalidate_step_L2:
        lwz     rtn_addr, 0(base_disp)
        cmplw   cr7, rtn_addr, addr
        cmplw   cr6, rtn_addr, data
        blt     cr7, dr_invalidate_step_L3
        bltl    cr6, dr_drop_entry
dr_invalidate_step_L3:
        lwzu    rtn_addr, 8(base_disp)
        cmplw   cr7, rtn_addr, addr
        cmplw   cr6, rtn_addr, data
        blt     cr7, dr_invalidate_step_L4
        bltl    cr6, dr_drop_entry
dr_invalidate_step_L4:
        lwzu    rtn_addr, 8(base_disp)
        cmplw   cr7, rtn_addr, addr
        cmplw   cr6, rtn_addr, data
        blt     cr7, dr_invalidate_step_L5
        bltl    cr6, dr_drop_entry
dr_invalidate_step_L5:
        lwzu    rtn_addr, 8(base_disp)
        cmplw   cr7, rtn_addr, addr
        cmplw   cr6, rtn_addr, data
        blt     cr7, dr_invalidate_step_L6
        bltl    cr6, dr_drop_entry
dr_invalidate_step_L6:
        addi    base_disp, base_disp, 8
        rlwinm  rtn_addr, base_disp, 0, 16, 26          // rtn_addr = base_disp[15:5] << 5
        cmpwi   cr7, rtn_addr, 0
        bf_likely 4*cr7+eq, dr_invalidate_step_L7
        lwz     base_disp, dr_hash_table(EmulatorStatePtr)
dr_invalidate_step_L7:
        bdnz    dr_invalidate_step_L2                   // CTR -= 1; branch while CTR != 0
        lwz     rtn_addr, 0xB88(EmulatorStatePtr)
        lwz     immed_data, 0xB8C(EmulatorStatePtr)
        stw     base_disp, 8(rtn_addr)
        lwz     base_disp, 12(rtn_addr)
        subf    immed_data, immed_data, base_disp       // immed_data = base_disp - immed_data
        cmplwi  cr7, immed_data, 0x0000
        cmplwi  cr6, immed_data, 0x0040
        stw     immed_data, 12(rtn_addr)
        lwz     base_disp, 8(rtn_addr)
        beq     cr7, dr_invalidate_step_L8
        blt     cr6, dr_invalidate_step_L1
        li      immed_data, 64
        b       dr_invalidate_step_L1
dr_invalidate_step_L8:
        lwz     base_disp, 0xB84(EmulatorStatePtr)
        addi    immed_data, EmulatorStatePtr, 0xB80
        lis     rtn_addr, 0x8000
        srw     rtn_addr, rtn_addr, base_disp
        mcrf    cr7, cr0                                // cr7 = cr0
dr_invalidate_step_L9:
        lwarx   data, 0, immed_data
        andc    data, data, rtn_addr                    // data = data & ~rtn_addr
        stwcx.  data, 0, immed_data
        bf_unlikely eq, dr_invalidate_step_L9
        addi    immed_data, EmulatorStatePtr, 0xB7C
dr_invalidate_step_L10:
        lwarx   data, 0, immed_data
        andc    data, data, rtn_addr                    // data = data & ~rtn_addr
        stwcx.  data, 0, immed_data
        bf_unlikely eq, dr_invalidate_step_L10
        mcrf    cr0, cr7                                // cr0 = cr7
        lwz     data, dr_invalidate_pending(EmulatorStatePtr)
        b       dr_invalidate_step

// Remove one lookup table entry and overwrite the first instruction of
// its translation with a branch to dr_stale_block, in case another block
// is chained directly to it.
dr_drop_entry:
        stw     zero, 0(base_disp)
        lwz     rtn_addr, dr_code_base(EmulatorStatePtr)
        lwz     immed_data, 4(base_disp)
        ori     rtn_addr, rtn_addr, dr_stale_block - dr_cb
        cmpwi   cr7, immed_data, 0
        stw     zero, 4(base_disp)
        subf    rtn_addr, immed_data, rtn_addr          // rtn_addr = rtn_addr - immed_data
        rlwinm  rtn_addr, rtn_addr, 0, 6, 29            // rtn_addr = rtn_addr[25:2] << 2
        oris    rtn_addr, rtn_addr, 0x4800
        beqlr   cr7
        stw     rtn_addr, 0(immed_data)
        dcbf    0, immed_data
        sync
        icbi    0, immed_data
        sync
        isync
        blr
        b       dr_drop_entry_L1
        ALIGN(64)
dr_drop_entry_L1:
        lwz     rtn_addr, -16(r23)
        stw     pc, -16(r23)
        lwz     data, -4(r23)
        lwz     immed_data, -12(r23)
        stw     rtn_addr, -8(r23)
        stw     pc, 0(base_disp)
        stw     data, 4(base_disp)
        mtctr   data
        stw     data, -12(r23)
        stw     immed_data, -4(r23)
        bctr
        b       dr_drop_entry_L2
        ALIGN(64)
dr_drop_entry_L2:
        stw     pc, 0(base_disp)
        stw     rtn_addr, 4(base_disp)
        bctr

// Entered from a translation that has been invalidated: look the address
// up afresh (which will retranslate it).
dr_stale_block:
        bt      cr_special_event_pending, dr_exit_to_interpreter
        lwz     base_disp, dr_records(EmulatorStatePtr)
dr_stale_block_L1:
        lwz     r23, dr_hash_table(EmulatorStatePtr)
        rlwimi  r23, pc, 4, 16, 26                      // r23[15:5] = pc[11:1]
        lwz     data, 0(r23)
        lwz     rtn_addr, 4(r23)
        cmpw    cr7, data, pc
        mtctr   rtn_addr
        lwzu    data, 8(r23)
        beq     cr7, dr_drop_entry_L2
        cmpw    cr7, data, pc
        lwzu    data, 8(r23)
        beq     cr7, dr_drop_entry_L1
        cmpw    cr7, data, pc
        lwzu    data, 8(r23)
        beq     cr7, dr_drop_entry_L1
        cmpw    cr7, data, pc
        addi    r23, r23, 8
        bt_unlikely 4*cr7+eq, dr_drop_entry_L1

// No translation exists.  Choose a slot in the set (an empty one if there
// is one, otherwise evict the last), then translate.
dr_translate_miss:
        sth     zero, 0xB34(EmulatorStatePtr)
dr_translate_miss_L1:
        lwzu    addr, -32(r23)
        lwzu    data, 8(r23)
        cmpwi   cr7, addr, 0
        cmpwi   cr6, data, 0
        beq     cr7, dr_translate_miss_L2
        lwzu    rtn_addr, 8(r23)
        beq     cr6, dr_translate_miss_L2
        cmpwi   cr7, rtn_addr, 0
        lwzu    immed_data, 8(r23)
        beq     cr7, dr_translate_miss_L2
        cmpwi   cr7, immed_data, 0
        addi    r23, r23, 8
        beq     cr7, dr_translate_miss_L2
        lwz     addr, dr_code_base(EmulatorStatePtr)
        lwz     data, -4(r23)
        ori     rtn_addr, addr, dr_stale_block - dr_cb
        subf    rtn_addr, data, rtn_addr                // rtn_addr = rtn_addr - data
        oris    immed_data, zero, 0x4800
        rlwimi  immed_data, rtn_addr, 0, 6, 29          // immed_data[25:2] = rtn_addr[25:2]
        stw     immed_data, 0(data)
        dcbf    0, data
        sync
        icbi    0, data
        sync
        isync
        stw     zero, -8(r23)
        stw     zero, -4(r23)
dr_translate_miss_L2:
        lwz     addr, dr_cache_ptr(EmulatorStatePtr)
        addi    addr, r23, -8
        stw     addr, dr_hash_slot(EmulatorStatePtr)
        crset   cr_dr_busy                              // the translator now owns blk_ofs, rec_ptr and out_ptr
        b       dr_translate

// The translator has produced a block.  Enter it in the lookup table,
// note in the page bitmap that this piece of 68K memory has been
// translated, and run it.  If the cache has filled up, start a flush and
// interpret instead.
dr_translate_done:
        crclr   cr_dr_busy
        lwz     data, dr_emit_ptr(EmulatorStatePtr)
        lwz     addr, dr_hash_slot(EmulatorStatePtr)
        lhz     rtn_addr, 0xB34(EmulatorStatePtr)
        sth     zero, 0xB34(EmulatorStatePtr)
        stw     data, 4(addr)                           // slot: code address
        stw     pc, 0(addr)                             // slot: 68K address
        sth     zero, 0xB36(EmulatorStatePtr)
        lwz     addr, dr_cache_limit(EmulatorStatePtr)
        add     data, data, rtn_addr
        mtctr   data
        cmplw   cr7, code_ptr, addr                     // past the end of the cache?
        stw     code_ptr, dr_cache_ptr(EmulatorStatePtr)
        lwz     disp_table, saved_disp_table(EmulatorStatePtr)
        lwz     code_ptr, saved_code_ptr(EmulatorStatePtr)
        bge     cr7, dr_translate_done_L2
        lwz     addr, dr_memory_limit(EmulatorStatePtr)
        lwz     data, dr_page_bitmap(EmulatorStatePtr)
        cmplw   cr6, pc, addr
        cmplwi  cr7, data, 0x0000
        rlwinm  addr, pc, 20, 12, 29                    // word index: one word per 16 KB of 68K memory
        lis     immed_data, 0x8000
        rlwinm  rtn_addr, pc, 23, 27, 31                // bit number: one bit per 512 bytes
        srw     immed_data, immed_data, rtn_addr
        bgt     cr6, dr_translate_done_L1
        beq     cr7, dr_translate_done_L1
        lwzx    rtn_addr, data, addr
        or      rtn_addr, rtn_addr, immed_data
        stwx    rtn_addr, data, addr
dr_translate_done_L1:
        lwz     rtn_addr, 0xB44(EmulatorStatePtr)
        lwz     addr, 0xB38(EmulatorStatePtr)
        lwz     data, 0xB3C(EmulatorStatePtr)
        mtcrf   0x0F, rtn_addr                          // cr4..cr7 = rtn_addr[15:0]
        lwz     rtn_addr, 0xB40(EmulatorStatePtr)
        bctr
dr_translate_done_L2:
        bl      dr_request_flush
        b       dr_exit_to_interpreter
        b       dr_invalidate_range
        ALIGN(64)

// Request invalidation of the translations for a range of 68K memory
// (addr = start, data = length).  Called for the 68K cache-flush
// operations, i.e. whenever 68K software announces that it has written
// code.
dr_invalidate_range:
        mflr    r23
        lwz     rtn_addr, dr_flush_pending(EmulatorStatePtr)
        cmpwi   cr4, data, 0
        cmplwi  cr5, rtn_addr, 0x0000
        beq     cr4, dr_invalidate_range_L12
        blt     cr4, dr_invalidate_range_L11
        bne     cr5, dr_invalidate_range_L12
        addi    data, data, 1
        add     data, addr, data
        cmplw   cr5, addr, data
        cmplwi  cr4, addr, 0x0080
        bge     cr5, dr_invalidate_range_L14
dr_invalidate_range_L1:
        ble     cr4, dr_invalidate_range_L13
        addi    addr, addr, -128
dr_invalidate_range_L2:
        lwz     immed_data, dr_memory_limit(EmulatorStatePtr)
        lwz     base_disp, dr_page_bitmap(EmulatorStatePtr)
        cmplw   cr4, data, immed_data
        cmplwi  cr5, base_disp, 0x0000
        srwi    rtn_addr, data, 14
        srwi    immed_data, addr, 14
        bgt     cr4, dr_invalidate_range_L6
        beq     cr5, dr_invalidate_range_L6
        subf    rtn_addr, immed_data, rtn_addr          // rtn_addr = rtn_addr - immed_data
        cmplwi  cr4, rtn_addr, 0x0000
        mtctr   rtn_addr
        bt_likely 4*cr4+eq, dr_invalidate_range_L5
        rlwinm  immed_data, addr, 20, 12, 29            // immed_data = addr[31:14] << 2
        lwzux   immed_data, base_disp, immed_data
        rlwinm  rtn_addr, addr, 23, 27, 31              // rtn_addr = addr[13:9]
        slw     immed_data, immed_data, rtn_addr
        cmplwi  cr4, immed_data, 0x0000
        bne     cr4, dr_invalidate_range_L6
        bdz     dr_invalidate_range_L4                  // CTR -= 1; branch when CTR == 0
dr_invalidate_range_L3:
        lwzu    immed_data, 4(base_disp)
        cmplwi  cr4, immed_data, 0x0000
        bne     cr4, dr_invalidate_range_L6
        bdnz    dr_invalidate_range_L3                  // CTR -= 1; branch while CTR != 0
dr_invalidate_range_L4:
        lwzu    immed_data, 4(base_disp)
        rlwinm  rtn_addr, data, 23, 27, 31              // rtn_addr = data[13:9]
        cntlzw  immed_data, immed_data                  // immed_data = number of leading zero bits in immed_data
        cmplw   cr4, immed_data, rtn_addr
        bt_likely 4*cr4+gt, dr_invalidate_range_L12
        b       dr_invalidate_range_L6
dr_invalidate_range_L5:
        rlwinm  immed_data, addr, 20, 12, 29            // immed_data = addr[31:14] << 2
        lwzx    immed_data, base_disp, immed_data
        rlwinm  rtn_addr, addr, 23, 27, 31              // rtn_addr = addr[13:9]
        slw     immed_data, immed_data, rtn_addr
        cntlzw  immed_data, immed_data                  // immed_data = number of leading zero bits in immed_data
        add     immed_data, immed_data, rtn_addr
        rlwinm  rtn_addr, data, 23, 27, 31              // rtn_addr = data[13:9]
        cmplw   cr4, immed_data, rtn_addr
        bt_likely 4*cr4+gt, dr_invalidate_range_L12
dr_invalidate_range_L6:
        mcrf    cr5, cr0                                // cr5 = cr0
        mtctr   r23
        addi    immed_data, EmulatorStatePtr, 0xB7C
dr_invalidate_range_L7:
        lwarx   rtn_addr, 0, immed_data
        lis     r23, 0x8000
        nor.    base_disp, rtn_addr, rtn_addr           // base_disp = ~(rtn_addr | rtn_addr)
        cntlzw  base_disp, base_disp                    // base_disp = number of leading zero bits in base_disp
        beq     dr_invalidate_range_L10
        srw     r23, r23, base_disp
        or      rtn_addr, rtn_addr, r23
        stwcx.  rtn_addr, 0, immed_data
        bf_unlikely eq, dr_invalidate_range_L7
        lwz     immed_data, dr_invalidate_requests(EmulatorStatePtr)
        slwi    rtn_addr, base_disp, 4
        add     immed_data, immed_data, rtn_addr
        lwz     rtn_addr, dr_hash_table(EmulatorStatePtr)
        stw     addr, 0(immed_data)
        stw     data, 4(immed_data)
        rlwimi  rtn_addr, addr, 4, 16, 26               // rtn_addr[15:5] = addr[11:1]
        stw     rtn_addr, 8(immed_data)
        srwi    addr, addr, 1
        addi    data, data, 2
        srwi    data, data, 1
        subf    rtn_addr, addr, data                    // rtn_addr = data - addr
        cmplwi  cr4, rtn_addr, 0x0800
        bf_likely 4*cr4+gt, dr_invalidate_range_L8
        li      rtn_addr, 0x800
dr_invalidate_range_L8:
        stw     rtn_addr, 12(immed_data)
        addi    immed_data, EmulatorStatePtr, 0xB80
dr_invalidate_range_L9:
        lwarx   rtn_addr, 0, immed_data
        lis     r23, 0x8000
        srw     r23, r23, base_disp
        or      rtn_addr, rtn_addr, r23
        stwcx.  rtn_addr, 0, immed_data
        bf_unlikely eq, dr_invalidate_range_L9
        mfctr   r23
        mcrf    cr0, cr5                                // cr0 = cr5
        b       dr_invalidate_range_L12
dr_invalidate_range_L10:
        mfctr   r23
        mcrf    cr0, cr5                                // cr0 = cr5
dr_invalidate_range_L11:
        bl      dr_request_flush
dr_invalidate_range_L12:
        mtlr    r23
        lwz     r23, dr_dispatch_vector(EmulatorStatePtr)
        blr
dr_invalidate_range_L13:
        mr      addr, zero
        b       dr_invalidate_range_L2
dr_invalidate_range_L14:
        li      data, -1
        b       dr_invalidate_range_L1
        b       dr_request_flush
        ALIGN(32)

// Ask for the whole translation cache to be discarded.
dr_request_flush:
        lwz     data, 0xB94(EmulatorStatePtr)
        li      addr, 32
        stw     addr, 0xB70(EmulatorStatePtr)
        stw     data, 0xB74(EmulatorStatePtr)
        li      data, 1
        stw     data, dr_flush_pending(EmulatorStatePtr)
        blr

dr_reset_requests:
        li      addr, 32
        stw     addr, 0xB70(EmulatorStatePtr)
        lwz     addr, 0xB94(EmulatorStatePtr)
        stw     addr, 0xB74(EmulatorStatePtr)
        li      addr, 1
        stw     addr, dr_flush_pending(EmulatorStatePtr)
        li      addr, 32
        mtctr   addr
        lwz     data, dr_invalidate_requests(EmulatorStatePtr)
dr_reset_requests_L1:
        stw     zero, 0(data)
        stw     zero, 4(data)
        stw     zero, 8(data)
        stw     zero, 12(data)
        addi    data, data, 16
        bdnz    dr_reset_requests_L1                    // CTR -= 1; branch while CTR != 0
        blr

// Called while an exception frame is being built.  If the faulting
// PowerPC instruction is inside the translation cache, work out the 68K
// address it corresponds to so that the frame holds a 68K pc.
dr_fault_fixup:
        mr      base_disp, data
        bt      cr_dr_busy, dr_fault_fixup_L3
        lwz     data, dr_cache_start(EmulatorStatePtr)
        cmplw   cr7, addr, data
        lwz     data, dr_cache_limit(EmulatorStatePtr)
        blt     cr7, dr_fault_fixup_L2
        cmplw   cr7, addr, data
        bge     cr7, dr_fault_fixup_L2
        lwz     data, 28(a7)
        lwz     r23, dr_hash_table(EmulatorStatePtr)
        rlwimi  r23, data, 4, 16, 26                    // r23[15:5] = data[11:1]
        lwz     rtn_addr, 0(r23)
        cmplw   cr7, rtn_addr, data
        beq     cr7, dr_fault_fixup_L1
        lwzu    rtn_addr, 8(r23)
        cmplw   cr7, rtn_addr, data
        beq     cr7, dr_fault_fixup_L1
        lwzu    rtn_addr, 8(r23)
        cmplw   cr7, rtn_addr, data
        beq     cr7, dr_fault_fixup_L1
        addi    r23, r23, 8
dr_fault_fixup_L1:
        lwz     rtn_addr, 4(r23)
        subf    rtn_addr, rtn_addr, addr                // rtn_addr = addr - rtn_addr
        stw     rtn_addr, 28(a7)
dr_fault_fixup_L2:
        lwz     r23, dr_dispatch_vector(EmulatorStatePtr)
        lwz     disp_table, saved_disp_table(EmulatorStatePtr)
        lwz     code_ptr, saved_code_ptr(EmulatorStatePtr)
        mr      data, base_disp
        blr
dr_fault_fixup_L3:
        mflr    rtn_addr
        crclr   cr_dr_busy
        lhz     addr, 0xB34(EmulatorStatePtr)
        sth     zero, 0xB34(EmulatorStatePtr)
        stw     addr, 28(a7)
        bl      dr_request_flush
        mtlr    rtn_addr
        lwz     addr, 0xB38(EmulatorStatePtr)
        stw     addr, 48(a7)
        lwz     addr, 0xB3C(EmulatorStatePtr)
        stw     addr, 52(a7)
        lwz     addr, 0xB40(EmulatorStatePtr)
        stw     addr, 56(a7)
        lwz     addr, 0xB44(EmulatorStatePtr)
        sth     addr, 44(EmulatorStatePtr)
        addi    pc, pc, 2
        lwz     r23, dr_dispatch_vector(EmulatorStatePtr)
        lwz     disp_table, saved_disp_table(EmulatorStatePtr)
        lwz     code_ptr, saved_code_ptr(EmulatorStatePtr)
        mr      data, base_disp
        blr

// Called while a bus error frame is being built for a fault inside
// translated code or inside the translator.
dr_fault_redirect:
        bt      cr_dr_busy, dr_resume_after_fault_L2
        lwz     addr, dr_cache_start(EmulatorStatePtr)
        lwz     data, dr_cache_limit(EmulatorStatePtr)
        cmplw   cr7, rtn_addr, addr
        cmplw   cr6, rtn_addr, data
        bltlr   cr7
        bgelr   cr6
        lwz     rtn_addr, dr_code_base(EmulatorStatePtr)
        lwz     data, 36(a7)
        ori     rtn_addr, rtn_addr, dr_resume_after_fault - dr_cb
        addi    data, data, 4
        sth     data, 0xB34(EmulatorStatePtr)
        blr

dr_resume_in_translator:
        crclr   cr_dr_busy

dr_resume_after_fault:
        nop
        stw     addr, 0xB38(EmulatorStatePtr)
        stw     data, 0xB3C(EmulatorStatePtr)
        mfcr    data
        stw     rtn_addr, 0xB40(EmulatorStatePtr)
        stw     data, 0xB44(EmulatorStatePtr)
        lwz     r23, dr_hash_table(EmulatorStatePtr)
        rlwimi  r23, pc, 4, 16, 26                      // r23[15:5] = pc[11:1]
        lwz     addr, 0(r23)
        cmplw   cr7, addr, pc
        beq     cr7, dr_resume_after_fault_L1
        lwzu    addr, 8(r23)
        cmplw   cr7, addr, pc
        beq     cr7, dr_resume_after_fault_L1
        lwzu    addr, 8(r23)
        cmplw   cr7, addr, pc
        beq     cr7, dr_resume_after_fault_L1
        lwzu    addr, 8(r23)
        cmplw   cr7, addr, pc
        beq     cr7, dr_resume_after_fault_L1
        addi    r23, r23, 8
        li      addr, -1
        sth     addr, 0xB36(EmulatorStatePtr)
        b       dr_translate_miss_L1
dr_resume_after_fault_L1:
        lwz     addr, 4(r23)
        lhz     data, 0xB34(EmulatorStatePtr)
        sth     zero, 0xB34(EmulatorStatePtr)
        add     addr, addr, data
        lwz     rtn_addr, 0xB40(EmulatorStatePtr)
        mtctr   addr
        lwz     addr, 0xB44(EmulatorStatePtr)
        lwz     data, 0xB3C(EmulatorStatePtr)
        mtcrf   0x0F, addr                              // cr4..cr7 = addr[15:0]
        lwz     addr, 0xB38(EmulatorStatePtr)
        bctr
dr_resume_after_fault_L2:
        lwz     addr, 48(a7)
        rlwinm  addr, addr, 0, 28, 26                   // addr = addr & 0xFFFFFFEF
        stw     addr, 48(a7)
        lwz     addr, 36(a7)
        lwz     rtn_addr, dr_code_base(EmulatorStatePtr)
        sth     addr, 0xB34(EmulatorStatePtr)
        ori     rtn_addr, rtn_addr, dr_resume_in_translator - dr_cb
        blr

dr_null_hook:
        blr

// Carve up the memory given to the recompiler (base and size are in the
// state block): lookup table (64 KB), a RAM table, the invalidation
// request table, the translation cache, the page bitmap at the top, and
// 2 KB for instruction records.  Then install the recompiler's entry
// points in the state block in place of the stubs.
dr_setup:
        lwz     data, 0x7C0(EmulatorStatePtr)
        stw     data, dr_hash_table(EmulatorStatePtr)
        lis     addr, 0x0001
        ori     addr, addr, 0x0000
        add     data, data, addr
        lwz     addr, 0xB18(EmulatorStatePtr)
        stw     data, 0xB1C(EmulatorStatePtr)
        add     data, data, addr
        stw     data, dr_invalidate_requests(EmulatorStatePtr)
        li      addr, 0x200
        add     data, data, addr
        stw     data, dr_cache_start(EmulatorStatePtr)
        lwz     data, 0x7C0(EmulatorStatePtr)
        lwz     addr, 0x7C4(EmulatorStatePtr)
        add     data, data, addr
        lis     addr, 0x5FFF                            // 0x5FFFEFF0 holds the address of the kernel's SystemInfo record ...
        ori     addr, addr, 0xE000
        lwz     addr, 0xFF0(addr)
        lwz     addr, 8(addr)                           // ... whose third word is the logical memory size
        addi    addr, addr, -1
        stw     addr, dr_memory_limit(EmulatorStatePtr)
        stw     zero, dr_page_bitmap(EmulatorStatePtr)
        clrrwi  rtn_addr, data, 5                       // rtn_addr = data & 0xFFFFFFE0
        addi    addr, addr, 0x200
        srwi    addr, addr, 9
        addi    addr, addr, 255
        srwi    addr, addr, 8
        stw     addr, 0xB94(EmulatorStatePtr)
        slwi    addr, addr, 5
        subf    rtn_addr, addr, rtn_addr                // rtn_addr = rtn_addr - addr
        lwz     addr, dr_cache_start(EmulatorStatePtr)
        addis   addr, addr, 1
        cmplw   cr7, addr, rtn_addr
        bgt     cr7, dr_setup_L1
        mr      data, rtn_addr
        stw     data, dr_page_bitmap(EmulatorStatePtr)
dr_setup_L1:
        addi    data, data, -0x800
        stw     data, dr_records(EmulatorStatePtr)
        addi    data, data, -0x800
        stw     data, dr_cache_limit(EmulatorStatePtr)
        lwz     data, dr_code_base(EmulatorStatePtr)
        ori     addr, data, dr_dispatch - dr_cb         // dr_dispatch
        stw     addr, dr_dispatch_vector(EmulatorStatePtr)
        ori     addr, data, dr_request_flush - dr_cb    // dr_request_flush
        stw     addr, dr_flush_vector(EmulatorStatePtr)
        ori     addr, data, dr_invalidate_range - dr_cb  // dr_invalidate_range
        stw     addr, dr_invalidate_vector(EmulatorStatePtr)
        ori     addr, data, dr_fault_fixup - dr_cb      // dr_fault_fixup
        stw     addr, dr_fault_fixup_vector(EmulatorStatePtr)
        ori     addr, data, dr_fault_redirect - dr_cb
        stw     addr, 0xA10(EmulatorStatePtr)
        li      addr, 16
        mtctr   addr
        addi    addr, data, 0x280                       // dr_line_0: the sixteen pass-1 decoders are 64 bytes apart
        addi    data, EmulatorStatePtr, 0xA18
dr_setup_L2:
        stwu    addr, 4(data)
        addi    addr, addr, 64
        bdnz    dr_setup_L2                             // CTR -= 1; branch while CTR != 0
        oris    data, zero, 0x0000
        ori     data, data, 0x21F8
        stw     data, 0x718(EmulatorStatePtr)
        b       dr_reset_requests
        blr

dr_credits:
        .ascii  "Dynamic Recompilation by Eric Traut, tuned by Bob Abeles, hacked by Murph"
        .space  7
D_182F8:
        .long   0x000021F8
D_182FC:
        .space  0x7D04
